def build_omnihi_managed_model_provider(
    environ: Mapping[str, str],
    *,
    http_client: httpx.Client | None = None,
) -> OmniHiManagedModelKeyProvider | None:
    names = (
        "THIRDSPACE_OMNIHI_AUTH_TYPE",
        "THIRDSPACE_OMNIHI_IDENTIFIER",
        "THIRDSPACE_OMNIHI_PASSWORD",
    )
    present = [bool(environ.get(name)) for name in names]
    if not any(present):
        return None
    if not all(present):
        raise RuntimeError("OMNIHI_INTEGRATION_NOT_CONFIGURED")
    try:
        timeout_seconds = float(
            environ.get("THIRDSPACE_OMNIHI_TIMEOUT_SECONDS", "10")
        )
        return OmniHiManagedModelKeyProvider(
            base_url=environ.get(
                "THIRDSPACE_OMNIHI_BASE_URL", "https://omnihi.ai"
            ),
            auth_type=environ["THIRDSPACE_OMNIHI_AUTH_TYPE"],
            identifier=environ["THIRDSPACE_OMNIHI_IDENTIFIER"],
            password=environ["THIRDSPACE_OMNIHI_PASSWORD"],
            country_code=environ.get("THIRDSPACE_OMNIHI_COUNTRY_CODE", "86"),
            client=http_client,
            timeout_seconds=timeout_seconds,
        )
    except ValueError as exc:
        raise RuntimeError("OMNIHI_INTEGRATION_NOT_CONFIGURED") from exc

def get_budget(self, *, provider_key_id: str, deadline_at: datetime | None = None) -> ManagedApiKeyBudget:
        if not provider_key_id or len(provider_key_id) > 128:
            raise ValueError("MODEL_CREDENTIAL_INVALID")
        return self._budget_from_list(
            bearer=self._login(deadline_at), provider_key_id=provider_key_id, deadline_at=deadline_at
        )

def _managed_credential_response(
        self,
        session: Session,
        row: ManagedModelCredential,
        token: str,
        *,
        account: AiCreditAccount | None = None,
    ) -> dict[str, Any]:
        if account is None:
            account = session.scalar(
                select(AiCreditAccount).where(
                    AiCreditAccount.managed_credential_id == row.id
                )
            )
        partner_visible = False
        if account is not None and account.user_id is not None:
            partner_visible = session.scalar(
                select(PartnerProfile.id).where(
                    PartnerProfile.user_id == account.user_id,
                    PartnerProfile.status == "active",
                    PartnerProfile.contract_status == "active",
                )
            ) is not None
        wallet = {
            "linked": False,
            "availableUnits": None,
            "referenceId": None,
        }
        if account is not None:
            omnihi_used_units = int(
                Decimal(account.confirmed_budget_used)
                * _AI_CREDIT_UNITS_PER_CNY
            )
            wallet = {
                "linked": True,
                "availableUnits": max(
                    0,
                    int(account.wallet_total_units)
                    - omnihi_used_units
                    - int(account.asr_committed_units)
                    - int(account.asr_reserved_units),
                ),
                "referenceId": account.public_ref,
            }
        return {
            "contractVersion": "growth-managed-model-credential-v1",
            "serviceId": row.service_id,
            "credential": {
                "type": "api_key",
                "token": token,
                "tokenPrefix": row.token_prefix,
            },
            "includedCredit": {
                "amount": f"{Decimal(row.included_amount):.8f}",
                "currency": row.currency,
            },
            "wallet": wallet,
            "partnerAccess": {
                "channelCenterVisible": partner_visible,
            },
        }
